-- ============================================================
-- WAG — Row Level Security policies + новые таблицы
-- Выполнить один раз в Supabase Dashboard → SQL Editor.
-- Идемпотентно: безопасно запускать повторно.
--
-- Модель доступа:
--   anon (публичный ключ NEXT_PUBLIC_SUPABASE_ANON_KEY)
--     → только SELECT контентных таблиц. Никаких записей.
--   service_role (SUPABASE_SERVICE_ROLE_KEY, только на сервере)
--     → обходит RLS; все мутации идут через /api/* роуты,
--       защищённые admin-сессией (см. src/proxy.ts).
--   Заявки (contacts) недоступны anon вообще — приём через
--   POST /api/contact (service role), чтение в /admin/contacts.
-- ============================================================

-- ── Таблица заявок с формы ──────────────────────────────────
create table if not exists public.contacts (
  id         bigint generated always as identity primary key,
  name       text not null,
  email      text not null,
  phone      text,
  message    text not null,
  status     text not null default 'new',  -- 'new' | 'processed'
  created_at timestamptz not null default now()
);

-- Для баз, где contacts уже существовала без статуса:
alter table public.contacts add column if not exists status text not null default 'new';

-- ── Отзывы (письма заказчиков, перенос из hardcoded
--    src/app/testimonials/page.tsx → src/lib/data.ts) ─────────
-- Если база успела создать старую упрощённую таблицу (с колонкой
-- author) и она пуста — пересоздаём с актуальной схемой.
do $mig$
begin
  if exists (
    select 1 from information_schema.columns
    where table_schema = 'public' and table_name = 'testimonials'
      and column_name = 'author'
  ) then
    -- вложенный if: планируется лениво, не падает на свежей базе
    if not exists (select 1 from public.testimonials) then
      drop table public.testimonials;
    end if;
  end if;
end $mig$;

create table if not exists public.testimonials (
  id          bigint generated always as identity primary key,
  client      text not null,               -- «ТОО «УКИЗ Актобе» · …»
  signatory   text not null default '',    -- кто подписал письмо
  role        text not null default '',    -- должность подписанта
  date_label  text,                        -- свободный текст: «5 января 2020»
  category    text not null default '',    -- «Строительство · 500 м»
  project     text not null default '',    -- описание объекта/работ
  quote       text not null,               -- цитата из письма
  order_index int  not null default 0,
  published   boolean not null default true,
  created_at  timestamptz not null default now()
);

-- ── Партнёры (логотипы в маркви + брошюре) ──────────────────
create table if not exists public.partners (
  id          bigint generated always as identity primary key,
  name        text not null,
  logo_url    text not null default '',  -- путь в /public/partners/ (URL-encoded) или Supabase Storage URL
  order_index int  not null default 0,
  published   boolean not null default true,
  created_at  timestamptz not null default now()
);

-- ── Включаем RLS везде ──────────────────────────────────────
alter table public.projects             enable row level security;
alter table public.design_projects      enable row level security;
alter table public.maintenance_projects enable row level security;
alter table public.contacts             enable row level security;
alter table public.testimonials         enable row level security;
alter table public.partners             enable row level security;

-- ── Политики: публичное чтение контента ─────────────────────
drop policy if exists "public read projects" on public.projects;
create policy "public read projects"
  on public.projects for select using (true);

drop policy if exists "public read design_projects" on public.design_projects;
create policy "public read design_projects"
  on public.design_projects for select using (true);

drop policy if exists "public read maintenance_projects" on public.maintenance_projects;
create policy "public read maintenance_projects"
  on public.maintenance_projects for select using (true);

drop policy if exists "public read testimonials" on public.testimonials;
create policy "public read testimonials"
  on public.testimonials for select using (published);

drop policy if exists "public read partners" on public.partners;
create policy "public read partners"
  on public.partners for select using (published);

-- contacts: политик нет → anon не может ни читать, ни писать.
-- service_role обходит RLS, поэтому серверные роуты работают.

-- Подчистить старую политику прямой вставки с клиента, если была:
drop policy if exists "anon insert contacts" on public.contacts;
drop policy if exists "public insert contacts" on public.contacts;

-- ============================================================
-- Seed-данные (вставляются только в пустые таблицы).
-- Тексты писем — дословные, адресованы West Capital Construction LLP
-- (подрядная компания группы) — НЕ переименовывать.
-- ============================================================

insert into public.testimonials (client, signatory, role, date_label, category, project, quote, order_index, published)
select * from (values
  ($q$ТОО «УКИЗ Актобе» · Aktobe Industrial Zone$q$, $q$Тулебаев А. Н.$q$, $q$Директор$q$, $q$5 января 2020$q$, $q$Содержание · 4,5 км$q$, $q$Текущее содержание и обслуживание подъездного железнодорожного пути в Индустриальной Зоне Актобе. 6 стрелочных переводов, 4,5 км путей, повышенный путь 140 м, две рампы 140 м, сливо-наливная эстакада для СУГ, 5 водопропускных труб ⌀1 м, 7 переездов.$q$, $q$За время сотрудничества текущее содержание и обслуживание подъездных железнодорожных путей ТОО «УКИЗ «Актобе» осуществляется квалифицированными специалистами. Качественно и своевременно устраняются все дефекты. Ответственность и профессионализм работников West Capital Construction LLP позволяют нам быть уверенными в безопасной эксплуатации наших подъездных железнодорожных путей.$q$, 0, true),
  ($q$ТОО «Актюбинская медная компания»$q$, $q$Бондаренко Н. С.$q$, $q$Генеральный директор$q$, null, $q$Перебортовка · 63 км$q$, $q$Перебортовка старогодней рельсошпальной решётки в объёме 63 км на базе АМК, п. Коктау, Хромтауский район.$q$, $q$Со своей стороны хотим отметить высококвалифицированный персонал, который ответственно подошёл к выполнению поставленных задач, и качественно в установленные договором сроки выполнил данные работы. West Capital Construction LLP имеет всю необходимую технику и оборудование для выполнения как демонтажных, так и строительно-монтажных работ.$q$, 1, true),
  ($q$ТОО «Актюбинская медная компания»$q$, $q$Бондаренко Н. С.$q$, $q$Генеральный директор$q$, null, $q$Содержание · 7,2 км + 20 км$q$, $q$Текущее содержание подъездных путей АМК в Коктау общей протяжённостью 7,2 км, 9 стрелочных переводов, 5 погрузочно-выгрузочных путей. Дочерняя ТОО «КазГеоруд» — соединительный участок ст. Жем — Терминал, 4 пути по 20 км.$q$, $q$Техническое обслуживание и текущее содержание такого путевого развития требует большой ответственности и профессионального внимания. Был заключён договор с West Capital Construction LLP, т. к. их специалисты зарекомендовали себя как профессиональные и добросовестные работники.$q$, 2, true),
  ($q$ТОО «Актюбинская медная компания»$q$, $q$Бондаренко Н. С.$q$, $q$Генеральный директор$q$, $q$21 сентября 2018$q$, $q$Реконструкция · ст. Рудная$q$, $q$Строительство соединительных путей в рамках реконструкции внутриплощадочных путей по станции Рудная. Соединительный путь № 7, путь № 1С, повышенные пути № 12 и № 13, энергетическая часть.$q$, $q$Сотрудники компании оперативно и качественно решали многочисленные вопросы, возникающие в процессе строительства. Все этапы дальнейшего строительства West Capital Construction LLP терпеливо согласовывала с руководством ТОО «АМК», чтобы учесть все наши пожелания. Профессионализм и добросовестность позволяют нам рекомендовать их как надёжную команду для строительных проектов любой сложности.$q$, 3, true),
  ($q$ТОО «Зерде-Керамика Актобе»$q$, $q$Тлеукабылов Е. Р.$q$, $q$Директор$q$, $q$Сентябрь 2021$q$, $q$Строительство · 481 м$q$, $q$Подъездной железнодорожный путь общей протяжённостью 481 м: повышенный путь 126 м, погрузочно-выгрузочная рампа 70 м, круглая ж/б водопропускная труба ⌀1 м, неохраняемый ж/д переезд.$q$, $q$Учитывая добросовестность и ответственность работников West Capital Construction LLP, а также серьёзный подход к выполняемой работе, мы уверены в безопасности эксплуатации железнодорожного пути и надеемся на дальнейшее сотрудничество.$q$, 4, true),
  ($q$ТОО «Зерде-Керамика Актобе»$q$, $q$Тлеукабылов Е. Р.$q$, $q$Директор$q$, null, $q$Демонтаж · 6,7 км$q$, $q$Демонтажные работы на ст. Айтеке Би. Демонтировано 6,7 км пути и 7 стрелочных переводов, выполнена переборка и складирование материалов верхнего строения пути по группам годности.$q$, $q$Ваши специалисты справились с выполнением данных работ качественно и в установленные сроки, что подтверждает Вашу ответственность и подготовленность. Учитывая, что Ваша компания работала с нами при строительстве объектов и при обслуживании путей, а теперь и при демонтажных работах, мы выражаем готовность на ещё более плодотворную работу.$q$, 5, true),
  ($q$ТОО «Компания Фаэтон»$q$, $q$Русманова В. Ю.$q$, $q$Директор$q$, $q$20 октября 2018$q$, $q$Содержание · рампа 70 м$q$, $q$Техническое обслуживание и текущее содержание подъездного железнодорожного пути. Погрузочно-выгрузочная рампа 70 м, круглая ж/б водопропускная труба ⌀1 м, два неохраняемых переезда с настилом из ж/б плит, кюветы для отвода талых вод.$q$, $q$Сотрудники West Capital Construction LLP отличаются ответственностью, добропорядочностью и профессионализмом. Обход, осмотр и исправление дефектов подъездного пути осуществляется качественно и своевременно. Ответственность, добросовестность и профессионализм работников дают нам уверенность в безопасной эксплуатации нашего подъездного железнодорожного пути.$q$, 6, true),
  ($q$ТОО «АлтынНұран»$q$, $q$Мурзабеков Ж. Н.$q$, $q$Директор$q$, $q$С сентября 2019$q$, $q$Содержание · 115 м$q$, $q$Текущее содержание и обслуживание подъездного железнодорожного пути общей протяжённостью 115 м с вагонными железнодорожными весами в г. Актобе.$q$, $q$Все работы по текущему содержанию железнодорожного пути и сооружений выполнялись высококвалифицированными специалистами. Учитывая добросовестность и ответственность работников, а также серьёзный подход к выполняемой работе, мы уверены в безопасности эксплуатации железнодорожного пути и надеемся на дальнейшее сотрудничество.$q$, 7, true),
  ($q$ТОО «Синтез Урал»$q$, $q$Морозов С. А.$q$, $q$Директор$q$, $q$С ноября 2024$q$, $q$Строительство · 500 м$q$, $q$Строительство подъездного железнодорожного пути ТОО «Синтез Урал» к объекту по производству смесевых продуктов мощностью 20 тыс. тонн в год. ЗКО, г. Уральск, с. Кардон, ст. Кардон, ст-е 1/1. Общая протяжённость 500 м, сливо-наливная эстакада для СУГ, вагонные весы, лебёдка.$q$, $q$Хочется отметить профессионализм и ответственность работников West Capital Construction LLP, а также оперативность решения вопросов, возникавших в ходе строительства. Высокий уровень организационной работы позволил качественно и в срок сдать объект в эксплуатацию.$q$, 8, true),
  ($q$ТОО «Portal KZ»$q$, $q$Нышанов М. М.$q$, $q$Директор$q$, null, $q$Строительство · ст. Никельтау$q$, $q$Строительство железнодорожного подъездного пути по ст. Никельтау, Актюбинского отделения перевозок АО «НК «КТЖ» — «Грузовые перевозки».$q$, $q$Строительство выполнено с чётким соблюдением всех условий договора: работа была выполнена в срок, в соответствии с техническим заданием. Следует отметить также высокий уровень организационной работы. В процессе выполнения рабочей документации между нашими организациями сложилась хорошая практика оперативного взаимодействия.$q$, 9, true),
