  ($q$ТОО «Нефтестройсервис ЛТД» · NSS$q$, $q$Отаров Р. К.$q$, $q$Директор$q$, $q$01 ноября 2022$q$, $q$Строительство · ст. Тендык$q$, $q$Строительство железнодорожного подъездного пути на базе ТОО «Нефтестройсервис ЛТД» по ст. Тендык, филиала АО «НК «КТЖ» — Атырауское отделение магистральной сети. Атырауская область, Геологский а/о, аул Новокирпичный.$q$, $q$Работы были выполнены в соответствии с действующими строительными нормами и правилами, согласно техническому заданию и условиям контракта, с надлежащим качеством и в установленный срок. West Capital Construction LLP проявила себя как высокопрофессиональная компания с наличием квалифицированных кадров.$q$, 11, true),
  ($q$ЧЛ «Ни К. А.»$q$, $q$Ни К. А.$q$, $q$Частный заказчик$q$, null, $q$Строительство · 41 разъезд$q$, $q$Строительство подъездного железнодорожного пути по станции Актобе-II, филиала АО «НК «КТЖ» — Грузовые перевозки. г. Актобе, район Алматы, 41 разъезд, участок № 547.$q$, $q$Компания показала себя как исполнительный подрядчик, выполняющий договорные обязательства с превосходным качеством работ и в установленные сроки. Применяемые компанией современные методы строительства верхнего строения железнодорожного пути и импортные материалы позволяют вести строительство и ремонт объектов с превосходным качеством.$q$, 12, true),
  ($q$ТОО «СП «Сине Мидас Строй»$q$, $q$Иманкулова Б. Т.$q$, $q$Исполнительный директор$q$, null, $q$Демонтаж · 850 м$q$, $q$Демонтаж подъездного железнодорожного пути на станции Ногайты, филиал «КТЖ» — «Актюбинское отделение магистральной сети» протяжённостью 850 м и повышенного пути 288 м из бетонных блоков.$q$, $q$Не можем не отметить высокий профессионализм работников West Capital Construction LLP, а также максимальную ответственность при выполнении поставленных задач. Учитывая то, что работы выполнены в установленные сроки и их качество не оставляет сомнений, надеемся на ещё более тесное сотрудничество.$q$, 13, true),
  ($q$ТОО «ПГС-Тамды»$q$, $q$Испанов А. К.$q$, $q$Директор$q$, null, $q$Строительство · ст. Тамды$q$, $q$Строительство железнодорожного подъездного пути на базе «ПГС-Тамды» по ст. Тамды, Актюбинского отделения АО «НК «КТЖ». РК, г. Актобе.$q$, $q$Профессиональный и ответственный подход к выполнению своей работы сотрудниками West Capital Construction LLP обеспечили строительство нашего железнодорожного пути необщего пользования в стационарный путь «на окно». Все согласования и переговоры с организациями АО «НК «КТЖ» велись своевременно.$q$, 14, true)
) as v(client, signatory, role, date_label, category, project, quote, order_index, published)
where not exists (select 1 from public.testimonials);

